"""Load configuration from files and strings."""

import os

from miniconf.errors import ConfigError
from miniconf.parser import parse_lines

INCLUDE_DIRECTIVE = "@include"


def _read_lines(path):
    with open(path, "r", encoding="utf-8") as fh:
        return fh.read().splitlines()


def _include_target(line):
    parts = line.strip().split(None, 1)
    if not parts or parts[0] != INCLUDE_DIRECTIVE:
        return None
    if len(parts) < 2 or not parts[1].strip():
        raise ConfigError("@include directive requires a path")
    return parts[1].strip()


def _expand(path, lines, stack):
    base_dir = os.path.dirname(os.path.abspath(path))
    expanded = []
    for raw in lines:
        target = _include_target(raw)
        if target is None:
            expanded.append(raw)
            continue
        target_path = os.path.join(base_dir, target)
        real = os.path.realpath(target_path)
        if real in stack:
            raise ConfigError(
                "include cycle detected: {!r} included from {!r}".format(
                    target_path, path
                )
            )
        if not os.path.isfile(target_path):
            raise ConfigError(
                "included file not found: {!r} (from {!r})".format(target_path, path)
            )
        try:
            child_lines = _read_lines(target_path)
        except OSError as exc:
            raise ConfigError(
                "cannot read included file {!r}: {}".format(target_path, exc)
            ) from exc
        stack.append(real)
        try:
            expanded.extend(_expand(target_path, child_lines, stack))
        finally:
            stack.pop()
    return expanded


def load(path):
    """Read and parse the configuration file at ``path``.

    ``@include <path>`` directives are expanded inline, resolving relative
    paths against the directory of the including file.
    """
    lines = _read_lines(path)
    return parse_lines(_expand(path, lines, [os.path.realpath(path)]))


def loads(text):
    """Parse configuration from a string."""
    return parse_lines(text.splitlines())
